Here is a complete, production-grade, highly concurrent Cloud-Native Service Mesh Sidecar Proxy written in C# (.NET 8/9). 

This implementation is self-contained and features **zero external dependencies**, leveraging modern asynchronous C# patterns, custom cryptographic certificate generation, thread-safe load-balancing algorithms, and an on-demand Prometheus-compatible telemetry exporter.

### Architecture Overview

```
                      +-------------------------------------------------+
                      |              Sidecar Proxy Service              |
                      |                                                 |
  Inbound mTLS        |   +-----------------------------------------+   |   Plaintext Forward
====================> |   |        Inbound mTLS Interceptor         |   | ====================>
  (Port 8443)         |   +-----------------------------------------+   |    Local App (5000)
                      |                                                 |
                      |   +-----------------------------------------+   |
  Outbound Plaintext  |   |      Load Balancing Policy Engine       |   |   Load Balanced Out
====================> |   |   (Round-Robin & Least-Latency EMAs)    |   | ====================>
  (Port 8080)         |   +-----------------------------------------+   |    Upstream Targets
                      |                                                 |
                      |   +-----------------------------------------+   |
                      |   |      Telemetry / Prometheus Exporter     |   | ===> Scraped by Prometheus
                      |   +-----------------------------------------+   |      (Port 9090)
                      +-------------------------------------------------+
```

---

### Implementation

Save this file as `Program.cs` and run it using `dotnet run` inside a standard console project.

```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Net.Security;
using System.Net.Sockets;
using System.Security.Authentication;
using System.Security.Cryptography;
using System.Security.Cryptography.X509Certificates;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace CloudNative.ServiceMesh.Sidecar
{
    public class Program
    {
        private static readonly CancellationTokenSource GlobalCts = new();

        public static async Task Main(string[] args)
        {
            Console.OutputEncoding = Encoding.UTF8;
            LogHeader("INITIALIZING CLOUD-NATIVE SIDECAR PROXY", ConsoleColor.Cyan);

            // 1. Generate mTLS Certificates dynamically in-memory
            Log("Generating in-memory cryptographic CA, Server, and Client Certificates...", ConsoleColor.Yellow);
            var (caCert, serverCert, clientCert) = CertificateAuthorityGenerator.GenerateCertificates();
            Log("Certificate chain established. [mTLS Ready]", ConsoleColor.Green);

            // Ports Configuration
            const int telemetryPort = 9090;
            const int outboundProxyPort = 8080;
            const int inboundProxyPort = 8443;
            const int mockBackendAppPort = 5000;

            // 2. Start Telemetry Reporter
            await using var telemetry = new TelemetryReporter(telemetryPort);
            telemetry.Start();

            // 3. Start Mock Upstream Services (representing target instances with differing latencies)
            using var upstreamA = new MockUpstreamService(5001, latencyMs: 15);   // Fast
            using var upstreamB = new MockUpstreamService(5002, latencyMs: 150);  // Slow
            using var upstreamC = new MockUpstreamService(5003, latencyMs: 50);   // Normal
            upstreamA.Start();
            upstreamB.Start();
            upstreamC.Start();

            // 4. Start Local Application Service (The target of inbound mTLS proxy traffic)
            using var localApp = new MockUpstreamService(mockBackendAppPort, latencyMs: 5);
            localApp.Start();

            // 5. Initialize Load Balancers
            var endpoints = new List<ServiceEndpoint>
            {
                new(new Uri("http://localhost:5001")),
                new(new Uri("http://localhost:5002")),
                new(new Uri("http://localhost:5003"))
            };

            var roundRobinLb = new RoundRobinLoadBalancer(endpoints);
            var leastLatencyLb = new LeastLatencyLoadBalancer(endpoints);

            // 6. Start Outbound Proxy (HTTP -> Load Balanced Upstream)
            // We start utilizing Round-Robin load balancing as default
            var outboundProxy = new OutboundProxyEngine(outboundProxyPort, roundRobinLb, telemetry);
            outboundProxy.Start();

            // 7. Start Inbound Proxy (mTLS Decryption -> Plaintext Local App)
            var inboundProxy = new InboundMtlsInterceptor(inboundProxyPort, mockBackendAppPort, serverCert, caCert, telemetry);
            inboundProxy.Start();

            // Give listeners a brief moment to warm up
            await Task.Delay(1000);

            // ==========================================
            // DEMONSTRATION WORKLOAD EXECUTION
            // ==========================================
            LogHeader("PHASE 1: OUTBOUND PROXY LOAD BALANCING (ROUND-ROBIN)", ConsoleColor.Cyan);
            await ExecuteOutboundSimulatedTrafficAsync(outboundProxyPort, totalRequests: 9);

            LogHeader("PHASE 2: OUTBOUND PROXY LOAD BALANCING (LEAST-LATENCY / ADAPTIVE)", ConsoleColor.Cyan);
            Log("Switching Outbound Proxy engine to Least-Latency Adaptive Routing...", ConsoleColor.Yellow);
            outboundProxy.SetLoadBalancer(leastLatencyLb);

            // Execute mock requests to allow Least-Latency engine to build latency profiles
            await ExecuteOutboundSimulatedTrafficAsync(outboundProxyPort, totalRequests: 15);

            LogHeader("PHASE 3: INBOUND MUTUAL TLS (mTLS) INTERCEPTION", ConsoleColor.Cyan);
            await ExecuteInboundMtlsSimulatedTrafficAsync(inboundProxyPort, clientCert, caCert);

            LogHeader("PHASE 4: METRICS SCRAPING (PROMETHEUS ENDPOINT)", ConsoleColor.Cyan);
            await ScrapePrometheusMetricsAsync(telemetryPort);

            // Shutdown sequence
            LogHeader("SHUTTING DOWN SIDECAR SERVICES", ConsoleColor.Red);
            GlobalCts.Cancel();
            await Task.Delay(500);
            Log("Sidecar proxy terminated gracefully.", ConsoleColor.Green);
        }

        private static async Task ExecuteOutboundSimulatedTrafficAsync(int proxyPort, int totalRequests)
        {
            using var client = new HttpClient();
            var tasks = new List<Task>();

            for (int i = 0; i < totalRequests; i++)
            {
                int requestId = i + 1;
                tasks.Add(Task.Run(async () =>
                {
                    try
                    {
                        var sw = Stopwatch.StartNew();
                        var response = await client.GetStringAsync($"http://localhost:{proxyPort}/api/resource?reqId={requestId}");
                        sw.Stop();
                        Log($"[Client] Req #{requestId} resolved in {sw.ElapsedMilliseconds}ms: {response.Trim()}", ConsoleColor.Gray);
                    }
                    catch (Exception ex)
                    {
                        Log($"[Client Error] Req #{requestId} failed: {ex.Message}", ConsoleColor.Red);
                    }
                }));
                // Stagger requests slightly to let latencies register cleanly
                await Task.Delay(100);
            }

            await Task.WhenAll(tasks);
        }

        private static async Task ExecuteInboundMtlsSimulatedTrafficAsync(int inboundPort, X509Certificate2 clientCert, X509Certificate2 caCert)
        {
            // Case A: Call WITH Mutually Trusted Client Certificate
            var handlerWithCert = new HttpClientHandler();
            handlerWithCert.ClientCertificates.Add(clientCert);

            // Bypass OS Trust store validation since our CA is dynamically constructed in memory
            handlerWithCert.ServerCertificateCustomValidationCallback = (sender, cert, chain, sslPolicyErrors) =>
            {
                if (cert == null) return false;
                return cert.Issuer == caCert.Subject; // Simple validation for demo
            };

            using var mtlsClient = new HttpClient(handlerWithCert);

            try
            {
                Log("[mTLS Client] Attempting connection to inbound proxy with valid client certificate...", ConsoleColor.Yellow);
                var response = await mtlsClient.GetStringAsync($"https://localhost:{inboundPort}/secure-endpoint");
                Log($"[mTLS Client Success] Decrypted response from application: {response.Trim()}", ConsoleColor.Green);
            }
            catch (Exception ex)
            {
                Log($"[mTLS Client Failed] Expected success, but failed: {ex.Message}", ConsoleColor.Red);
            }

            // Case B: Call WITHOUT Client Certificate (Should be rejected)
            var handlerNoCert = new HttpClientHandler
            {
                ServerCertificateCustomValidationCallback = (_, cert, _, _) => cert?.Issuer == caCert.Subject
            };
            using var nonMtlsClient = new HttpClient(handlerNoCert);

            try
            {
                Log("[mTLS Client] Attempting connection to inbound proxy WITHOUT client certificate (Expect Handshake Failure)...", ConsoleColor.Yellow);
                await nonMtlsClient.GetStringAsync($"https://localhost:{inboundPort}/secure-endpoint");
                Log("[mTLS Error] Target allowed access without mTLS!", ConsoleColor.Red);
            }
            catch (Exception)
            {
                Log("[mTLS Client Handshake Blocked] Success: Proxy correctly closed connection during mTLS handshake verification.", ConsoleColor.Green);
            }
        }

        private static async Task ScrapePrometheusMetricsAsync(int telemetryPort)
        {
            using var client = new HttpClient();
            try
            {
                Log($"Scraping telemetry data from http://localhost:{telemetryPort}/metrics ...\n", ConsoleColor.Yellow);
                var metrics = await client.GetStringAsync($"http://localhost:{telemetryPort}/metrics");
                Console.ForegroundColor = ConsoleColor.DarkGreen;
                Console.WriteLine(metrics);
                Console.ResetColor();
            }
            catch (Exception ex)
            {
                Log($"Failed to scrape metrics: {ex.Message}", ConsoleColor.Red);
            }
        }

        public static void Log(string message, ConsoleColor color = ConsoleColor.White)
        {
            lock (Console.Out)
            {
                Console.ForegroundColor = color;
                Console.WriteLine($"[{DateTime.Now:HH:mm:ss.fff}] {message}");
                Console.ResetColor();
            }
        }

        private static void LogHeader(string title, ConsoleColor color)
        {
            lock (Console.Out)
            {
                Console.ForegroundColor = color;
                Console.WriteLine(new string('=', 70));
                Console.WriteLine($" {title}");
                Console.WriteLine(new string('=', 70));
                Console.ResetColor();
            }
        }
    }

    #region Module 1: Inbound Traffic Interceptor (mTLS)

    public interface IMtlsInterceptor
    {
        void Start();
    }

    public class InboundMtlsInterceptor : IMtlsInterceptor
    {
        private readonly int _listeningPort;
        private readonly int _targetPlaintextPort;
        private readonly X509Certificate2 _serverCertificate;
        private readonly X509Certificate2 _trustedCa;
        private readonly TelemetryReporter _telemetry;
        private TcpListener? _listener;

        public InboundMtlsInterceptor(
            int listeningPort, 
            int targetPlaintextPort, 
            X509Certificate2 serverCertificate, 
            X509Certificate2 trustedCa, 
            TelemetryReporter telemetry)
        {
            _listeningPort = listeningPort;
            _targetPlaintextPort = targetPlaintextPort;
            _serverCertificate = serverCertificate;
            _trustedCa = trustedCa;
            _telemetry = telemetry;
        }

        public void Start()
        {
            _listener = new TcpListener(IPAddress.IPv6Any, _listeningPort);
            _listener.Server.SetSocketOption(SocketOptionLevel.IPv6, SocketOptionName.IPv6Only, false);
            _listener.Start();
            Task.Run(ListenLoopAsync);
            Program.Log($"Inbound mTLS Decryptor active on port {_listeningPort} (Routing plaintext -> :{_targetPlaintextPort})", ConsoleColor.Cyan);
        }

        private async Task ListenLoopAsync()
        {
            while (true)
            {
                try
                {
                    var client = await _listener!.AcceptTcpClientAsync().ConfigureAwait(false);
                    _ = Task.Run(() => HandleInboundConnectionAsync(client));
                }
                catch (Exception)
                {
                    break;
                }
            }
        }

        private async Task HandleInboundConnectionAsync(TcpClient client)
        {
            using (client)
            {
                var sslStream = new SslStream(
                    client.GetStream(), 
                    leaveInnerStreamOpen: false, 
                    userCertificateValidationCallback: ValidateClientCertificate);

                try
                {
                    // Configure server options for Mutual TLS (mTLS)
                    var authOptions = new SslServerAuthenticationOptions
                    {
                        ServerCertificate = _serverCertificate,
                        ClientCertificateRequired = true, // Force client authentication
                        CertificateRevocationMode = X509RevocationMode.NoCheck,
                        EnabledSslProtocols = SslProtocols.Tls12 | SslProtocols.Tls13
                    };

                    await sslStream.AuthenticateAsServerAsync(authOptions).ConfigureAwait(false);

                    // Successfully established mTLS! Let's forward raw decrypted bytes to local plaintext App
                    using var backendClient = new TcpClient();
                    await backendClient.ConnectAsync("127.0.0.1", _targetPlaintextPort).ConfigureAwait(false);
                    using var backendStream = backendClient.GetStream();

                    var sw = Stopwatch.StartNew();

                    // Bi-directional stream tunneling
                    var clientToBackend = TunnelStreamAsync(sslStream, backendStream);
                    var backendToClient = TunnelStreamAsync(backendStream, sslStream);

                    await Task.WhenAny(clientToBackend, backendToClient).ConfigureAwait(false);
                    sw.Stop();

                    _telemetry.RecordRequest("inbound", "GET", "/mtls-tunnel", "200");
                    _telemetry.RecordLatency("inbound", "GET", "/mtls-tunnel", sw.Elapsed.TotalSeconds);
                }
                catch (Exception ex)
                {
                    Program.Log($"[Inbound Interceptor Error] Tunnel closed or Handshake rejected: {ex.Message}", ConsoleColor.Red);
                }
            }
        }

        private async Task TunnelStreamAsync(Stream source, Stream destination)
        {
            byte[] buffer = new byte[8192];
            int read;
            while ((read = await source.ReadAsync(buffer).ConfigureAwait(false)) > 0)
            {
                await destination.WriteAsync(buffer.AsMemory(0, read)).ConfigureAwait(false);
                await destination.FlushAsync().ConfigureAwait(false);
            }
        }

        private bool ValidateClientCertificate(
            object sender, 
            X509Certificate? certificate, 
            X509Chain? chain, 
            SslPolicyErrors sslPolicyErrors)
        {
            if (certificate == null)
            {
                Program.Log("[mTLS Interceptor Reject] Client provided no certificate.", ConsoleColor.Red);
                return false;
            }

            var clientCert = new X509Certificate2(certificate);

            // Robust validation check: verifying that our customized local CA issued this client certificate
            using var chainEngine = new X509Chain();
            chainEngine.ChainPolicy.ExtraStore.Add(_trustedCa);
            chainEngine.ChainPolicy.VerificationFlags = X509VerificationFlags.AllowUnknownCertificateAuthority;
            chainEngine.ChainPolicy.RevocationMode = X509RevocationMode.NoCheck;

            bool isChainValid = chainEngine.Build(clientCert);
            if (!isChainValid)
            {
                // Fallback check: Direct signature matching for OS trust platform compatibility
                bool signatureValid = clientCert.Issuer == _trustedCa.Subject;
                if (!signatureValid)
                {
                    Program.Log($"[mTLS Interceptor Reject] Cert invalid chain. Issuer: '{clientCert.Issuer}' does not match expected Root.", ConsoleColor.Red);
                    return false;
                }
            }

            Program.Log($"[mTLS Interceptor Accept] Mutual verification succeeded for '{clientCert.Subject}'", ConsoleColor.Green);
            return true;
        }
    }

    #endregion

    #region Module 2: Load Balancing Policy Engine

    public class ServiceEndpoint
    {
        public Uri Address { get; }
        public long ActiveConnections;
        public double RollingLatencyMs { get; private set; } = 10.0; // Seed default base expectation
        private readonly object _latencyLock = new();

        public ServiceEndpoint(Uri address)
        {
            Address = address;
        }

        public void RecordLatency(double latencyMs)
        {
            lock (_latencyLock)
            {
                // Exponential Moving Average (EMA) with smoothing factor alpha = 0.3
                const double alpha = 0.3;
                RollingLatencyMs = (alpha * latencyMs) + ((1.0 - alpha) * RollingLatencyMs);
            }
        }
    }

    public interface ILoadBalancer
    {
        Task<ServiceEndpoint> SelectEndpointAsync(string serviceKey);
        void RecordLatency(ServiceEndpoint endpoint, double latencyMs);
    }

    /// <summary>
    /// Thread-safe Lock-Free Round-Robin load balancer using atomic CAS operations.
    /// </summary>
    public class RoundRobinLoadBalancer : ILoadBalancer
    {
        private readonly IReadOnlyList<ServiceEndpoint> _endpoints;
        private int _index = -1;

        public RoundRobinLoadBalancer(IReadOnlyList<ServiceEndpoint> endpoints)
        {
            _endpoints = endpoints ?? throw new ArgumentNullException(nameof(endpoints));
        }

        public Task<ServiceEndpoint> SelectEndpointAsync(string serviceKey)
        {
            if (_endpoints.Count == 0)
                throw new InvalidOperationException("No endpoints configured.");

            int nextIdx = Interlocked.Increment(ref _index);
            int selectedIdx = Math.Abs(nextIdx) % _endpoints.Count;
            return Task.FromResult(_endpoints[selectedIdx]);
        }

        public void RecordLatency(ServiceEndpoint endpoint, double latencyMs)
        {
            endpoint.RecordLatency(latencyMs);
        }
    }

    /// <summary>
    /// Evaluates both rolling latencies and active connection counts (Weighted Power of Two Choices approach)
    /// to avoid queuing up requests on degrading nodes.
    /// </summary>
    public class LeastLatencyLoadBalancer : ILoadBalancer
    {
        private readonly IReadOnlyList<ServiceEndpoint> _endpoints;
        private readonly Random _random = new();

        public LeastLatencyLoadBalancer(IReadOnlyList<ServiceEndpoint> endpoints)
        {
            _endpoints = endpoints ?? throw new ArgumentNullException(nameof(endpoints));
        }

        public Task<ServiceEndpoint> SelectEndpointAsync(string serviceKey)
        {
            if (_endpoints.Count == 0)
                throw new InvalidOperationException("No endpoints configured.");

            if (_endpoints.Count == 1)
                return Task.FromResult(_endpoints[0]);

            // Sample two random endpoints and pick the one with lower active impact (Latency * (Active Requests + 1))
            // This avoids herd effects and guarantees O(1) selection overhead.
            int idx1, idx2;
            lock (_random)
            {
                idx1 = _random.Next(_endpoints.Count);
                idx2 = _random.Next(_endpoints.Count);
                while (idx1 == idx2)
                {
                    idx2 = _random.Next(_endpoints.Count);
                }
            }

            var ep1 = _endpoints[idx1];
            var ep2 = _endpoints[idx2];

            double loadMetric1 = ep1.RollingLatencyMs * (Interlocked.Read(ref ep1.ActiveConnections) + 1);
            double loadMetric2 = ep2.RollingLatencyMs * (Interlocked.Read(ref ep2.ActiveConnections) + 1);

            var chosen = loadMetric1 < loadMetric2 ? ep1 : ep2;
            return Task.FromResult(chosen);
        }

        public void RecordLatency(ServiceEndpoint endpoint, double latencyMs)
        {
            endpoint.RecordLatency(latencyMs);
        }
    }

    #endregion

    #region Module 3: Telemetry Reporter (Prometheus Exporter)

    public class TelemetryReporter : IAsyncDisposable
    {
        private readonly HttpListener _listener;
        private readonly ConcurrentDictionary<string, long> _requestCounters = new();
        private readonly ConcurrentDictionary<string, ConcurrentBag<double>> _latencyHistograms = new();
        private readonly CancellationTokenSource _cts = new();
        private Task? _listeningTask;

        public TelemetryReporter(int port)
        {
            _listener = new HttpListener();
            _listener.Prefixes.Add($"http://localhost:{port}/");
        }

        public void Start()
        {
            _listener.Start();
            _listeningTask = Task.Run(ListenLoopAsync);
            Program.Log($"Telemetry exporter running on http://localhost:9090/metrics", ConsoleColor.Green);
        }

        public void RecordRequest(string direction, string method, string route, string status)
        {
            string key = $"direction=\"{direction}\",method=\"{method}\",route=\"{route}\",status=\"{status}\"";
            _requestCounters.AddOrUpdate(key, 1, (_, val) => val + 1);
        }

        public void RecordLatency(string direction, string method, string route, double latencySec)
        {
            string key = $"direction=\"{direction}\",method=\"{method}\",route=\"{route}\"";
            _latencyHistograms.GetOrAdd(key, _ => new ConcurrentBag<double>()).Add(latencySec);
        }

        private async Task ListenLoopAsync()
        {
            while (!_cts.Token.IsCancellationRequested)
            {
                try
                {
                    var context = await _listener.GetContextAsync().ConfigureAwait(false);
                    _ = Task.Run(() => ProcessMetricsRequestAsync(context));
                }
                catch (HttpListenerException) when (_cts.Token.IsCancellationRequested)
                {
                    break;
                }
                catch (Exception)
                {
                    // Suppress and continue
                }
            }
        }

        private async Task ProcessMetricsRequestAsync(HttpListenerContext context)
        {
            using var response = context.Response;
            if (context.Request.Url?.AbsolutePath != "/metrics")
            {
                response.StatusCode = (int)HttpStatusCode.NotFound;
                return;
            }

            var builder = new StringBuilder();

            // Render Request Counters
            builder.AppendLine("# HELP sidecar_requests_total Total HTTP requests intercepted by proxy.");
            builder.AppendLine("# TYPE sidecar_requests_total counter");
            foreach (var counter in _requestCounters)
            {
                builder.AppendLine($"sidecar_requests_total{{{counter.Key}}} {counter.Value}");
            }

            // Render Latency Gauge metrics
            builder.AppendLine("# HELP sidecar_request_duration_seconds Latency timings recorded.");
            builder.AppendLine("# TYPE sidecar_request_duration_seconds gauge");
            foreach (var histogram in _latencyHistograms)
            {
                var values = histogram.Value.ToArray();
                if (values.Length > 0)
                {
                    double avg = values.Average();
                    double max = values.Max();
                    builder.AppendLine($"sidecar_request_duration_seconds_avg{{{histogram.Key}}} {avg:F6}");
                    builder.AppendLine($"sidecar_request_duration_seconds_max{{{histogram.Key}}} {max:F6}");
                    builder.AppendLine($"sidecar_request_duration_count{{{histogram.Key}}} {values.Length}");
                }
            }

            byte[] buffer = Encoding.UTF8.GetBytes(builder.ToString());
            response.ContentType = "text/plain; version=0.0.4; charset=utf-8";
            response.ContentLength64 = buffer.Length;
            await response.OutputStream.WriteAsync(buffer).ConfigureAwait(false);
        }

        public async ValueTask DisposeAsync()
        {
            _cts.Cancel();
            try { _listener.Stop(); } catch { }
            if (_listeningTask != null) await _listeningTask.ConfigureAwait(false);
            _cts.Dispose();
        }
    }

    #endregion

    #region Sidecar Proxy Outbound Routing Engine

    public class OutboundProxyEngine
    {
        private readonly int _port;
        private ILoadBalancer _loadBalancer;
        private readonly TelemetryReporter _telemetry;
        private readonly HttpListener _listener;
        private readonly HttpClient _httpClient;

        public OutboundProxyEngine(int port, ILoadBalancer initialLoadBalancer, TelemetryReporter telemetry)
        {
            _port = port;
            _loadBalancer = initialLoadBalancer;
            _telemetry = telemetry;
            _listener = new HttpListener();
            _listener.Prefixes.Add($"http://*:{_port}/");

            // Dedicated proxy HttpClient optimized for connection pooling pooling socket resources
            var handler = new SocketsHttpHandler
            {
                PooledConnectionLifetime = TimeSpan.FromMinutes(5),
                MaxConnectionsPerServer = 100
            };
            _httpClient = new HttpClient(handler);
        }

        public void SetLoadBalancer(ILoadBalancer newLb)
        {
            _loadBalancer = newLb;
        }

        public void Start()
        {
            _listener.Start();
            Task.Run(ListenLoopAsync);
            Program.Log($"Outbound Proxy active on port {_port} using [{_loadBalancer.GetType().Name}]", ConsoleColor.Cyan);
        }

        private async Task ListenLoopAsync()
        {
            while (true)
            {
                try
                {
                    var ctx = await _listener.GetContextAsync().ConfigureAwait(false);
                    _ = Task.Run(() => HandleProxyRequestAsync(ctx));
                }
                catch
                {
                    break;
                }
            }
        }

        private async Task HandleProxyRequestAsync(HttpListenerContext context)
        {
            using var response = context.Response;
            var pathAndQuery = context.Request.Url?.PathAndQuery ?? "/";
            var resolvedEndpoint = await _loadBalancer.SelectEndpointAsync("backend").ConfigureAwait(false);

            Interlocked.Increment(ref resolvedEndpoint.ActiveConnections);
            var sw = Stopwatch.StartNew();

            try
            {
                var targetUri = new Uri(resolvedEndpoint.Address, pathAndQuery);
                using var requestMessage = new HttpRequestMessage(new HttpMethod(context.Request.HttpMethod), targetUri);

                // Copy Client headers to Upstream target request
                foreach (string headerName in context.Request.Headers)
                {
                    requestMessage.Headers.TryAddWithoutValidation(headerName, context.Request.Headers[headerName]);
                }

                if (context.Request.HasEntityBody)
                {
                    requestMessage.Content = new StreamContent(context.Request.InputStream);
                }

                using var responseMessage = await _httpClient.SendAsync(requestMessage).ConfigureAwait(false);
                sw.Stop();

                double durationMs = sw.Elapsed.TotalMilliseconds;

                // Track inside LB telemetry and Prometheus exporter
                _loadBalancer.RecordLatency(resolvedEndpoint, durationMs);
                _telemetry.RecordRequest("outbound", context.Request.HttpMethod, "/api/resource", ((int)responseMessage.StatusCode).ToString());
                _telemetry.RecordLatency("outbound", context.Request.HttpMethod, "/api/resource", sw.Elapsed.TotalSeconds);

                // Stream response back to calling process
                response.StatusCode = (int)responseMessage.StatusCode;
                foreach (var header in responseMessage.Headers)
                {
                    response.Headers.Add(header.Key, string.Join(",", header.Value));
                }

                await responseMessage.Content.CopyToAsync(response.OutputStream).ConfigureAwait(false);
            }
            catch (Exception ex)
            {
                sw.Stop();
                response.StatusCode = (int)HttpStatusCode.BadGateway;
                byte[] errorBuffer = Encoding.UTF8.GetBytes($"Mesh Sidecar Gateway Error: {ex.Message}");
                await response.OutputStream.WriteAsync(errorBuffer).ConfigureAwait(false);
            }
            finally
            {
                Interlocked.Decrement(ref resolvedEndpoint.ActiveConnections);
            }
        }
    }

    #endregion

    #region Mock In-Memory Infrastructure Components

    public class MockUpstreamService : IDisposable
    {
        private readonly int _port;
        private readonly int _latencyMs;
        private readonly HttpListener _listener;

        public MockUpstreamService(int port, int latencyMs)
        {
            _port = port;
            _latencyMs = latencyMs;
            _listener = new HttpListener();
            _listener.Prefixes.Add($"http://localhost:{_port}/");
        }

        public void Start()
        {
            _listener.Start();
            Task.Run(ListenLoopAsync);
        }

        private async Task ListenLoopAsync()
        {
            while (true)
            {
                try
                {
                    var context = await _listener.GetContextAsync().ConfigureAwait(false);
                    _ = Task.Run(() => ProcessRequestAsync(context));
                }
                catch
                {
                    break;
                }
            }
        }

        private async Task ProcessRequestAsync(HttpListenerContext context)
        {
            using var response = context.Response;
            if (_latencyMs > 0)
            {
                await Task.Delay(_latencyMs).ConfigureAwait(false);
            }

            byte[] buffer = Encoding.UTF8.GetBytes($"[App Port {_port}] Payload processing completed target latency: {_latencyMs}ms\n");
            response.ContentLength64 = buffer.Length;
            response.ContentType = "text/plain";
            response.StatusCode = 200;
            await response.OutputStream.WriteAsync(buffer).ConfigureAwait(false);
        }

        public void Dispose()
        {
