            byte[] serial = new byte[8];
            RandomNumberGenerator.Fill(serial);
            using var serverCert = serverRequest.Create(caCertWithKey, DateTimeOffset.UtcNow.AddMinutes(-5), DateTimeOffset.UtcNow.AddDays(30), serial);
